impl<T> Consumer<T> {
    pub closed spec fn wf(&self) -> bool {
        (*self.queue).wf()
            && self.consumer@.instance_id() == (*self.queue).instance@.id()
            && self.consumer@.value() == ConsumerState::Idle(self.head as nat)
            && (self.head as int) < (*self.queue).buffer@.len()
